using UnityEngine;
namespace HotelTogether {
 public sealed class HotelArmory:MonoBehaviour {
  public bool Initialized{get;private set;}public HotelFirearm[] Weapons{get;private set;}=System.Array.Empty<HotelFirearm>();Material steel,labelMaterial;GameObject rack;
  public void Initialize(){if(Initialized)return;var prefabs=Resources.LoadAll<HotelFirearm>("HotelTogetherFirearms");if(prefabs.Length==0)return;System.Array.Sort(prefabs,(a,b)=>string.CompareOrdinal(a.name,b.name));Initialized=true;steel=new Material(Shader.Find("Universal Render Pipeline/Lit")??Shader.Find("Standard"));steel.color=new Color(.12f,.16f,.18f);labelMaterial=new Material(steel);labelMaterial.color=new Color(.45f,.40f,.24f);
   rack=new GameObject("Storage room firearms rack");rack.transform.SetParent(transform,false);rack.transform.position=new Vector3(12,.025f,-31.75f);var parent=rack.transform;var obstacle=rack.AddComponent<UnityEngine.AI.NavMeshObstacle>();obstacle.shape=UnityEngine.AI.NavMeshObstacleShape.Box;obstacle.center=new Vector3(0,1.45f,0);obstacle.size=new Vector3(7,2.9f,.6f);obstacle.carving=true;Box("Armory back panel",parent,new Vector3(0,1.45f,-.14f),new Vector3(7f,2.9f,.08f),steel,true);
   for(int r=0;r<6;r++){float y=.15f+r*.46f;Box("Weapon shelf "+(r+1),parent,new Vector3(0,y,.06f),new Vector3(7f,.04f,.55f),steel,true);Box("Shelf identification strip "+(r+1),parent,new Vector3(0,y-.04f,.335f),new Vector3(7f,.16f,.035f),steel,false);}
   Weapons=new HotelFirearm[prefabs.Length];for(int i=0;i<prefabs.Length;i++){int col=i%5,row=i/5;float y=.15f+row*.46f;var gun=Instantiate(prefabs[i],parent);gun.name=prefabs[i].name;gun.transform.localPosition=new Vector3((col-2f)*1.35f,y+gun.size.y*.5f+.025f,.06f);gun.transform.localRotation=Quaternion.Euler(0,90,0);var rb=gun.GetComponent<Rigidbody>();rb.isKinematic=true;Weapons[i]=gun;var item=gun.GetComponent<HotelItem>();item.home=gun.transform.position;item.homeRotation=gun.transform.rotation;Label(parent,item.displayName,new Vector3((col-2f)*1.35f,y-.04f,.36f),.020f);}
   Box("Armory header sign",parent,new Vector3(0,2.98f,.24f),new Vector3(7,.24f,.035f),steel,false);Label(parent,"ARMORY  /  STORAGE ROOM",new Vector3(0,2.98f,.28f),.045f);var crate=Box("Ammunition resupply crate",parent,new Vector3(4.1f,.45f,.08f),new Vector3(.95f,.9f,.65f),labelMaterial,true);crate.AddComponent<HotelArmoryResupply>();var crateItem=crate.AddComponent<HotelItem>();crateItem.kind="armorySupply";crateItem.displayName="Ammunition resupply";crateItem.dimensions=new Vector3(.95f,.9f,.65f);Box("Ammo refill identification plate",parent,new Vector3(4.1f,.65f,.416f),new Vector3(.86f,.32f,.016f),steel,false);Label(parent,"AMMO\nLMB REFILL",new Vector3(4.1f,.65f,.428f),.025f);
  }
  static GameObject Box(string name,Transform parent,Vector3 point,Vector3 size,Material mat,bool solid){var go=GameObject.CreatePrimitive(PrimitiveType.Cube);go.name=name;go.transform.SetParent(parent,false);go.transform.localPosition=point;go.transform.localScale=size;go.GetComponent<Renderer>().sharedMaterial=mat;if(!solid){var collider=go.GetComponent<Collider>();collider.enabled=false;if(Application.isPlaying)Destroy(collider);else DestroyImmediate(collider);}return go;}
  static void Label(Transform parent,string text,Vector3 point,float size){HotelWorldText.Create(parent,text,point,size,new Color(.9f,.86f,.73f),true).GetComponent<HotelWorldText>().maximumDistance=9;}
  public void ResetArmory(){foreach(var gun in Weapons)if(gun)gun.ResetAmmo();foreach(var rocket in FindObjectsByType<HotelRocketProjectile>(FindObjectsSortMode.None))Destroy(rocket.gameObject);foreach(var body in FindObjectsByType<HotelZombieDeathPhysics>(FindObjectsSortMode.None))Destroy(body.gameObject);foreach(var h in GetComponentsInChildren<HotelHuman>())if(h.Dead)Destroy(h.gameObject);}
  void Start(){Initialize();}
  void OnDestroy(){if(steel)Destroy(steel);if(labelMaterial)Destroy(labelMaterial);}
 }
}
